practice.solution:
def heap_sort(a):
    h = []
    for x in a:
        h.append(x)
        i = len(h) - 1
        while i > 0 and h[(i - 1) // 2] > h[i]:
            p = (i - 1) // 2
            h[p], h[i] = h[i], h[p]
            i = p
    out = []
    while h:
        out.append(h[0])
        last = h.pop()
        if h:
            h[0] = last
            i = 0
            n = len(h)
            while True:
                l = 2 * i + 1
                r = 2 * i + 2
                s = i
                if l < n and h[l] < h[s]:
                    s = l
                if r < n and h[r] < h[s]:
                    s = r
                if s == i:
                    break
                h[i], h[s] = h[s], h[i]
                i = s
    return out

