practice.solution:
def dijkstra(n, edges, s):
    INF = 10 ** 9
    adj = [[] for i in range(n)]
    for u, v, w in edges:
        adj[u].append([v, w])
    d = [INF] * n
    d[s] = 0
    done = [0] * n
    for _ in range(n):
        u = -1
        for i in range(n):
            if not done[i] and d[i] < INF and (u == -1 or d[i] < d[u]):
                u = i
        if u == -1:
            break
        done[u] = 1
        for v, w in adj[u]:
            if d[u] + w < d[v]:
                d[v] = d[u] + w
    return [x if x < INF else -1 for x in d]

