practice.solution:
def mst(n, edges):
    parent = list(range(n))
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    total = 0
    for u, v, w in sorted(edges, key=lambda e: e[2]):
        a = find(u)
        b = find(v)
        if a != b:
            parent[a] = b
            total += w
    return total

